CREATE TABLE IF NOT EXISTS app_users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(64) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','viewer') NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS app_sessions (token_hash CHAR(64) PRIMARY KEY, user_id INT NOT NULL, csrf_token CHAR(64) NOT NULL, expires_at DATETIME(3) NOT NULL, INDEX(expires_at), FOREIGN KEY(user_id) REFERENCES app_users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS device_profiles (device_id VARCHAR(40) PRIMARY KEY, location VARCHAR(120) NOT NULL DEFAULT 'Unassigned', position DOUBLE NOT NULL DEFAULT 0.5, rssi DOUBLE NULL, uptime_ms BIGINT NULL, firmware VARCHAR(80) NULL, battery DOUBLE NULL, telemetry_at DATETIME(3) NULL, FOREIGN KEY(device_id) REFERENCES devices(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS sensor_calibrations (device_id VARCHAR(40) PRIMARY KEY, offset_x DOUBLE NOT NULL DEFAULT 0, offset_y DOUBLE NOT NULL DEFAULT 0, offset_z DOUBLE NOT NULL DEFAULT 0, sample_count INT NOT NULL DEFAULT 0, updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), FOREIGN KEY(device_id) REFERENCES devices(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS notification_config (id INT PRIMARY KEY, config JSON NOT NULL);
INSERT IGNORE INTO notification_config VALUES (1,'{"enabled":false,"recipient":"","critical":true,"offline":true,"warning":false,"cooldownSeconds":120}');
CREATE TABLE IF NOT EXISTS notification_deliveries (id BIGINT AUTO_INCREMENT PRIMARY KEY, alert_id BIGINT UNIQUE NOT NULL, device_id VARCHAR(40) NOT NULL, severity VARCHAR(12) NOT NULL, recipient VARCHAR(254) NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'queued', attempts INT NOT NULL DEFAULT 0, detail VARCHAR(255), created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), next_attempt_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), sent_at DATETIME(3), INDEX(status,next_attempt_at), FOREIGN KEY(alert_id) REFERENCES alerts(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS demo_runs (id BIGINT AUTO_INCREMENT PRIMARY KEY, state VARCHAR(20) NOT NULL, step INT NOT NULL DEFAULT 0, started_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), ended_at DATETIME(3));
INSERT IGNORE INTO device_profiles(device_id,location,position) SELECT id,IF(source='simulation','Midspan / simulated','East tower / prepared'),IF(source='simulation',0.5,0.75) FROM devices;
